def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = 2

    sep_row = next((r for r in range(h)
                    if all(grid[r][c] == marker for c in range(w))), None)
    sep_col = next((c for c in range(w)
                    if all(grid[r][c] == marker for r in range(h))), None)

    obj_color = next(v for v in counts if v not in (background, marker))
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == obj_color]
    out = [row[:] for row in grid]

    if sep_row is not None:
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        if rmax < sep_row:
            line = rmax + 1 if rmax + 1 < sep_row else rmin - 1
        else:
            line = rmin - 1 if rmin - 1 > sep_row else rmax + 1
        if 0 <= line < h:
            out[line] = [8] * w
    else:
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)
        if cmax < sep_col:
            line = cmax + 1 if cmax + 1 < sep_col else cmin - 1
        else:
            line = cmin - 1 if cmin - 1 > sep_col else cmax + 1
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8

    return out
